'use strict'

import { getHitboxPath, getHitboxPoints, getHitboxQuarters } from '../utils/hitbox'
import resource from '../resource'

// What a revealed entrance lets through: everything
const OPEN_HITBOX = '00000000'

class Tile {
  constructor (column, line, x, y, width, height, hitbox, sprite, destructible, tileTransition, start, secret) {
    this.column = column
    this.line = line
    this.x = x
    this.y = y
    this.width = width
    this.height = height
    this.hitbox = hitbox
    this.sprite = sprite
    this.transition = undefined
    this.tilePath = this.getTilePath()
    this.blockPath = this.getBlockPath()
    // A hidden entrance: how it opens (SECRET_* in constant.js), and what it becomes ({ sprite }, and for a
    // push the tile pushed: { block: { x, y } }). Its transition only works once it is revealed
    this.destructible = destructible
    this.secret = secret
    this.revealed = false
    // What the tile was, before a push moved a rock onto it or away from it
    this.original = { sprite, hitbox }
    this.tileTransition = tileTransition
    this.start = start
  }

  get isHidden () {
    return !!this.destructible && !this.revealed
  }

  // The entrance shows (for good, as in the original game)
  reveal () {
    this.revealed = true
    this.applyReveal()
  }

  applyReveal () {
    this.sprite = resource.getSprite(this.secret?.sprite) ?? this.sprite
    this.setHitbox(OPEN_HITBOX)
  }

  // Back to what it was when the screen was loaded (a pushed rock goes back), the entrance staying open
  restore () {
    this.sprite = this.original.sprite
    this.setHitbox(this.original.hitbox)
    if (this.revealed) {
      this.applyReveal()
    }
  }

  setHitbox (hitbox) {
    this.hitbox = hitbox
    this.recomputePaths()
  }

  recomputePaths () {
    this.tilePath = this.getTilePath()
    this.blockPath = this.getBlockPath()
  }

  clone () {
    return new Tile(this.column, this.line, this.x, this.y, this.width, this.height, this.hitbox, this.sprite.clone(), this.destructible, this.tileTransition.clone(), this.start, this.secret && structuredClone(this.secret))
  }

  draw (context, offsetX, offsetY) {
    const tileOffsetX = offsetX !== undefined ? this.x + offsetX : this.x
    const tileOffsetY = offsetY !== undefined ? this.y + offsetY : this.y

    this.sprite.draw(context, tileOffsetX, tileOffsetY, this.width, this.height)
  }

  getTilePath () {
    const path = new Path2D()
    path.rect(this.x, this.y, this.width, this.height)

    return path
  }

  // Blocking polygon used by the collisions, always in sync with the hitbox string (edited in the editor)
  get blockPoints () {
    if (typeof this.hitbox !== 'string') {
      return []
    }

    return getHitboxPoints(this.x, this.y, this.width, this.height, this.hitbox)
  }

  // What blocks Link: the quarters of the tile (see getHitboxQuarters)
  get blockQuarters () {
    if (typeof this.hitbox !== 'string') {
      return []
    }

    return getHitboxQuarters(this.x, this.y, this.width, this.height, this.hitbox)
  }

  getBlockPath () {
    if (typeof this.hitbox !== 'string') {
      return
    }

    return getHitboxPath(this.x, this.y, this.width, this.height, this.hitbox)
  }
}

export { Tile }
