'use strict'

import InputManager from '../service/input-manager'
import resource from '../resource'
import { listenMenuKeys } from './menu-keys'
import { drawCenteredText } from './screen-text'
import { SPRITE_TEXT_COLOR_RED, SPRITE_TEXT_COLOR_WHITE } from '../constant'

const TRIFORCE_SIZE = 96
// The invitation to press Start blinks (milliseconds on, then off)
const BLINK_PERIOD = 500

// Shown when the page opens and after "retry": the game starts on Start. The original logo is not in
// the sprites, so the title is written with the font of the game
class TitleScreen {
  constructor (onStart, getKeyLabel) {
    this.onStart = onStart
    this.getKeyLabel = getKeyLabel
    this.visible = false
    this.stopListening = undefined
  }

  show () {
    this.visible = true
    this.stopListening?.()
    this.stopListening = listenMenuKeys({
      [InputManager.ACTION_START]: () => {
        this.hide()
        this.onStart()
      }
    })
  }

  hide () {
    this.visible = false
    this.stopListening?.()
    this.stopListening = undefined
  }

  draw (context, width, height) {
    context.fillStyle = 'black'
    context.fillRect(0, 0, width, height)

    const triforce = resource.getSprite('item_triforce_fragment')
    context.save()
    context.imageSmoothingEnabled = false
    // The golden image (the sprite blinks blue and gold)
    triforce?.images[1]?.draw(context, (width - TRIFORCE_SIZE) / 2, 48, TRIFORCE_SIZE, TRIFORCE_SIZE)
    context.restore()

    drawCenteredText(context, 'the legend of', SPRITE_TEXT_COLOR_WHITE, width, 176, 1.5)
    drawCenteredText(context, 'zelda', SPRITE_TEXT_COLOR_RED, width, 212, 3)

    if (Math.floor(performance.now() / BLINK_PERIOD) % 2 === 0) {
      const key = this.getKeyLabel(InputManager.getBinding(InputManager.ACTION_START))
      drawCenteredText(context, `press ${key} to start`.toLowerCase(), SPRITE_TEXT_COLOR_WHITE, width, height - 96)
    }
  }
}

export { TitleScreen }
